export function ChainIcon({
  chainKey,
  className = 'w-5 h-5',
  size,
}: {
  chainKey: SupportedChainKey | string;
  className?: string;
  size?: number;
}) {
  switch (chainKey) {
    case 'bsc':
      return <BscIcon className={className} size={size} />;
    case 'eth':
      return <EthIcon className={className} size={size} />;
    case 'btc':
      return <BtcIcon className={className} size={size} />;
    case 'pol':
      return <PolIcon className={className} size={size} />;
    case 'base':
      return <BaseIcon className={className} size={size} />;
    case 'arbitrum':
      return <ArbIcon className={className} size={size} />;
    case 'op':
      return <OpIcon className={className} size={size} />;
    case 'avax':
      return <AvaxIcon className={className} size={size} />;
    case 'plasma':
      return <PlasmaIcon className={className} size={size} />;
    default:
      return null;
  }
}

export function TokenIcon({
  token,
  className = 'w-4 h-4',
  size,
}: {
  token: SupportedToken | string;
  className?: string;
  size?: number;
}) {
  switch (token) {
    case 'USDT':
      return <UsdtIcon className={className} size={size} />;
    case 'USDC':
      return <UsdcIcon className={className} size={size} />;
    case 'ETH':
      return <EthIcon className={className} size={size} />;
    case 'BTC':
      return <BtcIcon className={className} size={size} />;
    case 'BNB':
      return <BscIcon className={className} size={size} />;
    case 'POL':
      return <PolIcon className={className} size={size} />;
    case 'AVAX':
      return <AvaxIcon className={className} size={size} />;
    case 'XPL':
      return <PlasmaIcon className={className} size={size} />;
    default:
      return null;
  }
}
